(function(root){
const stages=[
{id:'basics',name:'入门',subtitle:'先学会走，再学会下',icon:'兵',intro:'认识七种棋子的走法与限制，养成落子前先看安全的习惯。',goal:'能独立完成一局，不走违例棋。'},
{id:'opening',name:'进阶',subtitle:'让每一枚棋子都有用',icon:'馬',intro:'练习常见开局的出子思路。示范是布局入门路线，并非唯一最佳走法。',goal:'理解出子、占位与保护，不靠死记棋谱。'},
{id:'tactics',name:'提高',subtitle:'看见一步以后的变化',icon:'炮',intro:'从将军、捉双、牵制和交换入手，学会同时观察进攻与对手的反击。',goal:'落子前计算“我走、他应、我再走”。'},
{id:'endgame',name:'精进',subtitle:'把优势变成胜势',icon:'車',intro:'学习常见的基础杀法。观察控制逃路的棋子，比只看将军的棋子更重要。',goal:'认识典型杀形，理解各子如何协同。'}
];
const base=()=>[[4,0,'bk'],[4,9,'rk'],[4,5,'rp']];
const M=(x,y,X,Y,text)=>({x,y,X,Y,text});
const lessons=[
{id:'rook',stage:'basics',title:'车：直来直往',time:2,summary:'沿横线、竖线行走，路径上不能有棋子。',points:['车每步可沿一条直线走任意格，不能斜走，也不能跳过棋子。','落点有敌子可以吃掉；有己方棋子就不能落在那里。','车的活动空间很重要，先看整条路线是否畅通。'],mistake:'不要把车当成炮：车不能隔着一枚棋子吃子。',setup:[...base(),[0,7,'rr']],steps:[M(0,7,0,3,'把红车沿竖线向前移动四格，体会长距离的直线行动。')],takeaway:'路径畅通，车就能直达。'},
{id:'horse',stage:'basics',title:'马：走日，先看腿',time:3,summary:'先直走一格，再斜走一格；马腿不能被挡。',points:['马的终点与起点组成“日”字：一边两格，另一边一格。','沿两格方向的第一格就是马腿，有任何棋子都会蹩住。','红马正前方有兵，向前跳的路线被挡；右侧路线仍然可走。'],mistake:'目标格是空的，不代表马一定能跳到；还要检查马腿。',setup:[...base(),[1,9,'rh'],[1,8,'rp']],steps:[M(1,9,3,8,'红马向右跳日。正前方的兵挡住向前的马腿，但不挡这条路线。')],takeaway:'想好落点，再检查对应的马腿。'},
{id:'cannon',stage:'basics',title:'炮：隔一子打',time:3,summary:'不吃子时像车，吃子时必须隔一枚炮架。',points:['炮不吃子时沿直线移动，路径必须畅通。','吃子时，炮与目标之间必须恰好有一枚棋子。','炮架可以是己方棋子，也可以是对方棋子。'],mistake:'没有炮架或有两枚炮架，都不能这样吃子。',setup:[...base(),[1,7,'rc'],[1,5,'rp'],[1,2,'br']],steps:[M(1,7,1,2,'利用中间的红兵作炮架，红炮隔子吃掉黑车。')],takeaway:'开炮之前，先数炮架：恰好一枚。'},
{id:'elephant',stage:'basics',title:'相：守住自己的半场',time:2,summary:'相走田字，不过河，也不能塞相眼。',points:['相沿斜线走两格，起点与终点组成“田”字。','田字中央的交叉点是相眼；相眼有棋子就不能走。','红相始终留在红方半场，黑象也不能过河。'],mistake:'相不是远距离斜走的棋子，每次只走一个田字。',setup:[...base(),[2,9,'re']],steps:[M(2,9,4,7,'把红相飞到中间，相眼畅通，终点仍在己方半场。')],takeaway:'走田、看眼、不过河。'},
{id:'palace',stage:'basics',title:'将与士：九宫里的守护',time:3,summary:'将帅直走一步，仕士斜走一步，都留在九宫。',points:['将帅在九宫中横走或竖走一格，不能走进被攻击的位置。','仕士在九宫内斜走一格，保护将帅周围的要点。','两将不能在同一直线上直接照面；被将军时必须先解将。'],mistake:'不能只想着进攻：应将优先，任何一步都不能让自己的将帅受攻击。',setup:[...base(),[3,9,'ra']],steps:[M(3,9,4,8,'红仕斜上一步，进入九宫中心，为帅提供保护。')],takeaway:'将走直，士走斜，活动范围在九宫。'},
{id:'pawn',stage:'basics',title:'兵：过河就多一种选择',time:3,summary:'过河前只向前，过河后能横走，始终不能后退。',points:['兵卒每次走一格；红兵向棋盘上方前进，黑卒相反。','过河前只能向前；过河后还可以向左或向右一格。','过河兵依然不能后退，也不会像国际象棋一样升变。'],mistake:'刚走到河边还不能横走，必须进入对方半场。',setup:[...base(),[0,5,'rp'],[8,3,'bp']],steps:[M(0,5,0,4,'红兵向前一步进入对方半场，完成过河。'),M(8,3,8,4,'黑卒向前一步。演示中的黑方应手也由你操作。'),M(0,4,1,4,'过河之后，红兵可以横走一格。')],takeaway:'过河增横走，前进不回头。'},
{id:'central-cannon',stage:'opening',title:'中炮：把火力对准中路',time:4,summary:'认识中炮开局，理解炮架与后续出子的关系。',points:['中炮是把炮平到中路，利用中兵作炮架向前施压。','中炮不是立刻就能吃中卒，仍要观察炮架、保护与反击。','对手出马后，自己也要发展马车，避免只动一枚炮。'],mistake:'开局不要执着连续将军；把大子调动出来通常更重要。',initial:true,steps:[M(1,7,4,7,'红炮平到中路，形成中炮布局。'),M(1,0,2,2,'黑马正常出动，保护中路并增加活动空间。'),M(1,9,2,7,'红马也跳出，形成炮与马的呼应。')],takeaway:'炮瞄中路，马车及时出动。'},
{id:'screen-horses',stage:'opening',title:'双马出动：先站稳，再进攻',time:4,summary:'认识屏风马的基本结构，学会左右协调出子。',points:['双马分别向中路跳出，可以保护中兵并争取更多控制点。','这是屏风马结构的基础认识，完整布局还需要结合炮、车和兵。','开局要兼顾两翼，少让某一侧的大子一直困在原地。'],mistake:'出马不是万能防守，仍要看马腿是否被挡、落点是否安全。',initial:true,steps:[M(1,9,2,7,'红方先发展左侧的马，向中路靠拢。'),M(1,2,4,2,'黑方平炮到中路，向中兵施压。'),M(7,9,6,7,'红方另一匹马也向中路跳出，形成双马呼应的基础结构。')],takeaway:'左右协调，比一子独进更稳。'},
{id:'rook-development',stage:'opening',title:'出车：先找畅通的路线',time:3,summary:'认识起横车，练习让车尽早参与棋局。',points:['车起到兵线后方的横线，再横向调动，是一种常见出车方式。','不能为了出车忽略对手的进攻，要先检查将帅和关键子力的安全。','本课是出车路线示例；实战中也可根据局势选择直车。'],mistake:'车不一定要沿原路直冲；横向调动也能找到好位置。',initial:true,steps:[M(0,9,0,8,'红车先向前一步，走上可横向活动的路线。'),M(8,3,8,4,'黑卒前进一步，双方轮流行棋。'),M(0,8,4,8,'红车沿空横线调到中路，增加活动空间。')],takeaway:'找到通路，让大子走出来。'},
{id:'fork',stage:'tactics',title:'捉双：将军时顺手攻车',time:4,summary:'一枚马同时攻击两个目标，利用应将争取吃子机会。',points:['捉双是一步同时攻击两个重要目标，对手往往难以兼顾。','如果其中一个目标是将帅，对手必须先应将。','将军后不要急着结束计算，要继续看下一步能吃什么。'],mistake:'马能否吃车仍要看马腿；将军也不代表一定赢子。',setup:[[3,1,'bk'],[4,9,'rk'],[3,5,'rh'],[6,2,'br']],steps:[M(3,5,4,3,'红马跳日，同时将军并攻击右侧黑车。'),M(3,1,3,0,'黑将退到宫内底线，先解除将军。'),M(4,3,6,2,'红马顺势吃车，兑现捉双的收益。')],takeaway:'优先看将军，再看它能否兼攻大子。'},
{id:'pin',stage:'tactics',title:'牵制：车后面还有将',time:3,summary:'看穿棋子背后的目标，理解“不能随便走开”。',points:['黑车挡在红车与黑将之间，承担着遮挡攻击的任务。','黑车若横向走开，会暴露黑将，因此行动受到限制。','识别这种牵制后，再考虑吃子、增援或施压。'],mistake:'被牵制不等于完全不能动；沿原线挡将或吃掉攻击子仍可能合法。',setup:[[4,0,'bk'],[3,9,'rk'],[4,6,'rr'],[4,2,'br']],steps:[M(4,6,4,2,'红车吃掉同线黑车，同时向黑将发出将军。')],takeaway:'看目标，也要看目标身后的将帅。'},
{id:'discovered-check',stage:'tactics',title:'闪将：移开前子，亮出后车',time:3,summary:'前面的棋子离开，让后方的车直接攻击将帅。',points:['红马暂时挡在红车与黑将之间，黑将尚未被红车攻击。','移开红马，红车的整条线路就被打开。','闪将常可兼顾吃子或占位，本课先认识打开线路的基本形状。'],mistake:'线路上如果还有其他棋子，移开一子也未必能形成将军。',setup:[[4,0,'bk'],[3,9,'rk'],[4,6,'rr'],[4,4,'rh']],steps:[M(4,4,2,3,'红马跳开，后方红车的中路完全畅通，形成闪将。')],takeaway:'一子移开，另一子的力量才显现。'},
{id:'exchange',stage:'tactics',title:'交换：把三步都算完',time:4,summary:'吃子之前，先算清对方回吃和自己的再吃。',points:['眼前吃到一个车，不等于已经赚到一个车。','沿着“我吃、他吃、我再吃”看完整条变化。','这里红方以一车换黑方一车一炮，收益来自后续接应。'],mistake:'不要只数第一步吃到的棋子，要比较整段交换后的结果。',setup:[...base(),[0,6,'rr'],[2,3,'rr'],[0,3,'br'],[0,0,'bc'],[0,1,'bp']],steps:[M(0,6,0,3,'红车先吃黑车，但还没有算完。'),M(0,0,0,3,'黑炮利用黑卒作炮架，回吃红车。'),M(2,3,0,3,'另一辆红车接应吃炮，完成整段交换。')],takeaway:'先算回吃，再决定要不要吃。'},
{id:'two-rooks',stage:'endgame',title:'双车错：一车封路，一车将军',time:4,summary:'两辆车控制相邻横线，让将帅没有退路。',points:['一辆红车控制黑将下方的整条横线，负责封住前进的路。','另一辆车切到黑将所在横线发出将军。','关键在于两车分工：一个将军，一个封锁逃路。'],mistake:'只把两辆车堆在同一条线上，反而可能相互遮挡。',setup:[...base(),[0,1,'rr'],[1,2,'rr']],steps:[M(1,2,1,0,'红车切到底线将军；另一辆红车封住下一横线，形成将死。')],mate:true,takeaway:'分开两条线，合起来封住九宫。'},
{id:'double-cannon',stage:'endgame',title:'重炮：两门炮互作炮架',time:4,summary:'两炮同线配合，让对方难以挡将或移动。',points:['后炮借前炮作炮架，隔炮攻击黑将。','若黑士到中路挡住后炮，又会变成前炮的炮架。','杀形还依赖逃路被限制；不是所有两炮同线都能将死。'],mistake:'两炮必须配合具体位置，先检查将的逃路和双方能否吃炮。',setup:[[4,0,'bk'],[3,0,'ba'],[5,0,'ba'],[4,9,'rk'],[4,2,'rc'],[3,5,'rc']],steps:[M(3,5,4,5,'后炮平到中路，借前炮将军；黑将无路可走，挡将也无效。')],mate:true,takeaway:'后炮借前炮，挡一门又通另一门。'},
{id:'king-support',stage:'endgame',title:'白脸将：帅也能远程助攻',time:4,summary:'利用将帅不能照面的规则，配合车限制逃路。',points:['红帅控制着没有其他棋子的中路，黑将不能走入这条线。','红车从侧面切入黑将所在竖线，封住黑将的上下退路。','残局中帅不仅需要保护，也能参与控制关键路线。'],mistake:'白脸将依赖中间没有棋子，线路被挡住就不成立。',setup:[[3,0,'bk'],[4,9,'rk'],[0,2,'rr']],steps:[M(0,2,3,2,'红车对黑将将军。黑将不能前进，也不能向中路走入与红帅照面的线路。')],mate:true,takeaway:'将帅不照面，也能变成进攻的力量。'}
];
function position(lesson,E){if(lesson.initial)return E.initial();const b=Array.from({length:10},()=>Array(9).fill(null));for(const [x,y,p] of lesson.setup)b[y][x]=p;return b;}
const api={stages,lessons,position};if(typeof module!=='undefined')module.exports=api;else root.XQLessons=api;
})(globalThis);
